        {"kind": "trace", "sql": "SELECT u.attr_http_response_status_code st, count(*) n, round(avg(CAST(f.duration AS DOUBLE))/1e6,1) food_ms FROM abnormal_traces u JOIN abnormal_traces f ON f.parent_span_id=u.span_id AND f.service_name='ts-food-service' AND f.attr_span_kind='Server' WHERE u.service_name='ts-ui-dashboard' AND u.attr_span_kind='Server' GROUP BY 1", "claim": "Food-side server spans for failing requests finish in about 52ms; the ts-travel-service server spans are normal (about 12ms, status 200)."}
      ]
    },
    {
      "service": "ts-ui-dashboard",
