      "evidence": [
        {"kind": "trace", "sql": "SELECT u.attr_http_response_status_code st, count(*) n, round(avg(CAST(u.duration AS DOUBLE))/1e6,1) ui_ms, round(avg(CAST(f.duration AS DOUBLE))/1e6,1) food_ms FROM abnormal_traces u JOIN abnormal_traces f ON f.parent_span_id=u.span_id AND f.service_name='ts-food-service' AND f.attr_span_kind='Server' WHERE u.service_name='ts-ui-dashboard' AND u.attr_span_kind='Server' GROUP BY 1 ORDER BY 1", "claim": "Ui-dashboard food-path requests take 2.5-4.2s while the food call inside them takes about 55ms, for both 200 and 500 responses."},
        {"kind": "trace", "sql": "SELECT u.attr_http_response_status_code st, count(*) n, round(avg(CAST(u.duration AS DOUBLE))/1e6,1) ui_ms, round(avg(CAST(f.duration AS DOUBLE))/1e6,1) food_ms FROM normal_traces u JOIN normal_traces f ON f.parent_span_id=u.span_id AND f.service_name='ts-food-service' AND f.attr_span_kind='Server' WHERE u.service_name='ts-ui-dashboard' AND u.attr_span_kind='Server' GROUP BY 1 ORDER BY 1", "claim": "Normal period: the same ui-dashboard food-path requests take about 30ms, matching the food call time."},
        {"kind": "trace", "sql": "SELECT span_name, count(*) c, round(quantile_cont(duration,0.95)/1e6,1) p95_ms FROM abnormal_traces WHERE service_name='ts-ui-dashboard' AND attr_span_kind='Server' AND span_name NOT LIKE '%foodservice%' GROUP BY 1 ORDER BY c DESC LIMIT 5", "claim": "Ui-dashboard requests to other paths (preserve, consign, assurance) are not slowed; only the food path is affected."}
