    {"from": "ts-food-service", "to": "ts-ui-dashboard", "evidence": [{"kind": "trace", "sql": "SELECT u.attr_http_response_status_code st, count(*) n FROM abnormal_traces u JOIN abnormal_traces f ON f.parent_span_id=u.span_id AND f.service_name='ts-food-service' AND f.attr_span_kind='Server' WHERE u.service_name='ts-ui-dashboard' AND u.attr_span_kind='Server' AND f.attr_http_response_status_code=500 GROUP BY 1", "claim": "Food's 500 responses (from its aborted travel call) surface as 500 on ui-dashboard's food-path server spans, reaching the user."}
